//! Benchmark inputs: generated by fixed-seed xorshift, two runs see
//! exact same bytes. Sets intentionally hostile (duplicate vertices,
//! degenerate triangles, NaN/Infinity/-0, mirror matrices, deep hierarchies).
use serde_json::{json, Value};

pub(crate) struct Xorshift(u64);
impl Xorshift {
    pub(crate) fn new(seed: u64) -> Self {
        Self(seed | 1)
    }
    pub(crate) fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    pub(crate) fn below(&mut self, bound: usize) -> usize {
        (self.next() % bound.max(1) as u64) as usize
    }
    /// Finite float in [-512, 512).
    pub(crate) fn coordinate(&mut self) -> f32 {
        (self.next() % 1_048_576) as f32 / 1024.0 - 512.0
    }
}

/// Triangle soup: one vertex in two is exact duplicate, 1 in 512 degenerate.
pub(crate) fn mesh(seed: u64, triangles: usize) -> (Vec<f32>, Vec<u32>) {
    let mut rng = Xorshift::new(seed);
    let vertices = (triangles / 2).max(3);
    let mut positions = Vec::with_capacity(vertices * 3);
    for slot in 0..vertices {
        if slot % 2 == 1 && slot >= 2 {
            let previous = (slot - 2) * 3;
            let (x, y, z) = (
                positions[previous],
                positions[previous + 1],
                positions[previous + 2],
            );
            positions.extend_from_slice(&[x, y, z]);
        } else {
            positions.extend_from_slice(&[rng.coordinate(), rng.coordinate(), rng.coordinate()]);
        }
    }
    let mut indices = Vec::with_capacity(triangles * 3);
    for face in 0..triangles {
        let a = rng.below(vertices) as u32;
        if face % 512 == 0 {
            indices.extend_from_slice(&[a, a, a]);
            continue;
        }
        indices.extend_from_slice(&[a, rng.below(vertices) as u32, rng.below(vertices) as u32]);
    }
    (positions, indices)
}

/// Same mesh, with non-finite positions and negative zeros seeded inside.
pub(crate) fn mesh_hostile(seed: u64, triangles: usize) -> (Vec<f32>, Vec<u32>) {
    let (mut positions, indices) = mesh(seed, triangles);
    let poison = [f32::NAN, f32::INFINITY, f32::NEG_INFINITY, -0.0, 0.0];
    for slot in (0..positions.len()).step_by(997) {
        positions[slot] = poison[slot / 997 % poison.len()];
    }
    (positions, indices)
}

/// Matrix column by column, non-uniform, mirror 1 in 3 nodes (det < 0).
fn matrix(rng: &mut Xorshift, mirrored: bool) -> Vec<f64> {
    let scale = [
        0.25 + (rng.next() % 400) as f64 / 100.0,
        0.25 + (rng.next() % 400) as f64 / 100.0,
        if mirrored { -1.0 } else { 1.0 } * (0.25 + (rng.next() % 400) as f64 / 100.0),
    ];
    let shear = (rng.next() % 200) as f64 / 100.0 - 1.0;
    vec![
        scale[0],
        shear,
        0.0,
        0.0,
        0.0,
        scale[1],
        shear,
        0.0,
        shear,
        0.0,
        scale[2],
        0.0,
        (rng.next() % 2000) as f64 / 10.0,
        (rng.next() % 2000) as f64 / 10.0,
        (rng.next() % 2000) as f64 / 10.0,
        1.0,
    ]
}

/// glTF scene of `count` nodes in chains of `depth` levels, mixed matrices/TRS.
pub(crate) fn scene(seed: u64, count: usize, depth: usize) -> Value {
    let mut rng = Xorshift::new(seed);
    let mut nodes = Vec::with_capacity(count);
    for id in 0..count {
        let mut node = if id % 2 == 0 {
            json!({ "matrix": matrix(&mut rng, id % 3 == 0) })
        } else {
            json!({"translation":[(rng.next()%1000) as f64/10.0,(rng.next()%1000) as f64/10.0,(rng.next()%1000) as f64/10.0],
              "rotation":[0.5,0.5,0.5,0.5],
              "scale":[0.5+(rng.next()%300) as f64/100.0,0.5+(rng.next()%300) as f64/100.0,-0.5-(rng.next()%300) as f64/100.0]})
        };
        if id % depth != depth - 1 && id + 1 < count {
            node["children"] = json!([id + 1]);
        }
        nodes.push(node);
    }
    json!({ "nodes": nodes })
}

/// `count` primitive pages: bounds, cluster sphere and parent sphere, all present.
pub(crate) fn pages(seed: u64, count: usize) -> Vec<Value> {
    let mut rng = Xorshift::new(seed);
    let mut out = Vec::with_capacity(count);
    for _ in 0..count {
        let number = |rng: &mut Xorshift| (rng.next() % 1_000_000) as f64 / 997.0;
        out.push(json!({
          "min":[number(&mut rng),number(&mut rng),number(&mut rng)],
          "max":[number(&mut rng),number(&mut rng),number(&mut rng)],
          "sphere":[number(&mut rng),number(&mut rng),number(&mut rng),number(&mut rng)],
          "parentSphere":[number(&mut rng),number(&mut rng),number(&mut rng),number(&mut rng)]}));
    }
    out
}

/// Level clusters: `groups` groups of 32 clusters of 128 triangles sharing edges.
pub(crate) fn clusters(seed: u64, count: usize, triangles: usize) -> Vec<Vec<u32>> {
    let mut rng = Xorshift::new(seed);
    // Clusters draw from common vertex pool, otherwise no edges shared.
    let band = (count * triangles).max(8);
    (0..count)
        .map(|id| {
            let base = id * triangles / 2;
            let mut indices = Vec::with_capacity(triangles * 3);
            for _ in 0..triangles {
                let a = (base + rng.below(triangles * 2)) % band;
                indices.extend_from_slice(&[
                    a as u32,
                    ((a + 1 + rng.below(3)) % band) as u32,
                    ((a + 4 + rng.below(3)) % band) as u32,
                ]);
            }
            indices
        })
        .collect()
}
